function maxSubarraySum(nums) {
  const EMPTY = { sum: 0, best: -Infinity, prefix: -Infinity, suffix: -Infinity };
  const leaf = value => ({ sum: value, best: value, prefix: value, suffix: value });
  const merge = (left, right) => ({
    sum: left.sum + right.sum,
    best: Math.max(left.best, right.best, left.suffix + right.prefix),
    prefix: Math.max(left.prefix, left.sum + right.prefix),
    suffix: Math.max(right.suffix, right.sum + left.suffix),
  });

  let size = 1;
  while (size < nums.length) {
    size *= 2;
  }
  const tree = new Array(2 * size).fill(EMPTY);
  for (let i = 0; i < nums.length; i++) {
    tree[size + i] = leaf(nums[i]);
  }
  for (let node = size - 1; node >= 1; node--) {
    tree[node] = merge(tree[2 * node], tree[2 * node + 1]);
  }

  const update = (index, item) => {
    let node = size + index;
    tree[node] = item;
    while (node > 1) {
      node >>= 1;
      tree[node] = merge(tree[2 * node], tree[2 * node + 1]);
    }
  };

  const positions = new Map();
  for (let i = 0; i < nums.length; i++) {
    if (!positions.has(nums[i])) {
      positions.set(nums[i], []);
    }
    positions.get(nums[i]).push(i);
  }

  let answer = tree[1].best;
  for (const [value, indices] of positions) {
    for (const i of indices) {
      update(i, EMPTY);
    }
    answer = Math.max(answer, tree[1].best);
    for (const i of indices) {
      update(i, leaf(value));
    }
  }
  return answer;
}

