function maxSubarraySum(nums) {
  // Try no removal and every allowed removal, checking every subarray of what is left.
  const bestOf = arr => {
    let best = -Infinity;
    for (let i = 0; i < arr.length; i++) {
      let sum = 0;
      for (let j = i; j < arr.length; j++) {
        sum += arr[j];
        best = Math.max(best, sum);
      }
    }
    return best;
  };
  let answer = bestOf(nums);
  for (const x of new Set(nums)) {
    const rest = nums.filter(v => v !== x);
    if (rest.length > 0) answer = Math.max(answer, bestOf(rest));
  }
  return answer;
}

