function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  if (size === 'large') {
    const n = 2000, shape = pick(4);
    // A few repeated values, positives split by repeated walls, all negative, or anything in range.
    const pool = Array.from({ length: 5 + pick(60) }, () => pick(2000001) - 1000000);
    const walls = Array.from({ length: 1 + pick(4) }, () => -1 - pick(1000000));
    return [Array.from({ length: n }, () => {
      if (shape === 0) return pool[pick(pool.length)];
      if (shape === 1) return rand() < 0.1 ? walls[pick(walls.length)] : pick(1001) - 100;
      if (shape === 2) return -1 - pick(1000000);
      return pick(2000001) - 1000000;
    })];
  }
  // Small: tiny arrays with many repeats, sometimes only two or three distinct values, sometimes all negative.
  const n = 1 + pick(10), shape = pick(3);
  const pool = Array.from({ length: 1 + pick(3) }, () => pick(13) - 6);
  return [Array.from({ length: n }, () => {
    if (shape === 0) return pick(13) - 6;
    if (shape === 1) return pool[pick(pool.length)];
    return -1 - pick(6);
  })];
}
